/* WARNING: 本项目专属“粘人精”，严禁出现 Kiro、Krio、周棋洛等任何相关英文或拼音命名！ */
<script setup lang="ts">
import { ref, watch } from 'vue'
import type { MusicPlaylist, MusicTrack } from '../../../types/music'
const props = defineProps<{ visible: boolean; playlist: MusicPlaylist | null; tracks: MusicTrack[]; loading: boolean; error: string; filtering: boolean; filterChecked: number; filterTotal: number; filterRemoved: number; editable?: boolean }>()
const emit = defineEmits<{ (e: 'close'): void; (e: 'filter'): void; (e: 'playAll'): void; (e: 'play', track: MusicTrack, index: number): void; (e: 'reorder', from: number, to: number): void; (e: 'addToPlaylist', track: MusicTrack): void }>()
const sorting = ref(false)
const failedCover = ref(false)
watch(() => props.visible, visible => { if (!visible) sorting.value = false })
watch(() => props.playlist?.coverUrl, () => { failedCover.value = false })
</script>

<template>
  <div v-if="visible" class="detail-mask" @click="emit('close')"><section class="detail-sheet" @click.stop>
    <header><div><strong>歌单详情</strong><small>{{ loading ? '正在读取完整歌单…' : filtering ? `正在筛选 ${filterChecked}/${filterTotal}` : filterRemoved ? `${tracks.length} 首歌曲 · 已筛除 ${filterRemoved} 首` : `${tracks.length} 首歌曲` }}</small></div><button aria-label="关闭" @click="emit('close')">×</button></header>
    <div class="detail-hero"><span class="detail-cover"><img v-if="playlist?.coverUrl && !failedCover" :src="playlist.coverUrl" alt="" @error="failedCover = true" /><i v-else>单</i></span><div><strong>{{ playlist?.name || '歌单' }}</strong><small><span v-if="playlist?.isPrivate" class="private-label">私密</span>{{ playlist?.ownerName || (editable ? '我的歌单' : playlist?.sourceId) }}</small><p v-if="playlist?.description">{{ playlist.description }}</p></div></div>
    <div class="detail-toolbar"><span>{{ playlist?.playCount || 0 }} 次播放</span><div class="toolbar-actions"><button v-if="editable" class="filter-button" :disabled="tracks.length < 2" @click="sorting = !sorting">{{ sorting ? '完成排序' : '手动排序' }}</button><button class="filter-button" :disabled="loading || filtering || !tracks.length" @click="emit('filter')">{{ filtering ? `筛选 ${filterChecked}/${filterTotal}` : '筛除不可播' }}</button><button :disabled="loading || filtering || !tracks.length" @click="emit('playAll')">播放全部</button></div></div>
    <div class="detail-list"><div v-if="error" class="detail-state">{{ error }}</div><div v-else-if="loading" class="detail-state">正在加载歌曲列表</div><div v-else-if="!tracks.length" class="detail-state">这个歌单还没有歌曲，可从歌曲旁的“添加到歌单”按钮加入。</div><div v-for="(track,index) in tracks" v-else :key="track.id" class="track-row"><button class="track-main" @click="emit('play', track, index)"><span class="track-index">{{ index + 1 }}</span><span class="track-info"><strong>{{ track.title }}</strong><small>{{ track.artist }} · {{ track.album }}</small></span><span class="track-action">▶</span></button><div v-if="sorting" class="track-order"><button :disabled="index === 0" aria-label="上移歌曲" @click="emit('reorder', index, index - 1)">↑</button><button :disabled="index === tracks.length - 1" aria-label="下移歌曲" @click="emit('reorder', index, index + 1)">↓</button></div><button v-else class="track-add" title="添加到歌单" aria-label="添加到歌单" @click="emit('addToPlaylist', track)"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg></button></div></div>
  </section></div>
</template>

