padding-right:12px}.detail-toolbar>span{display:none}.toolbar-actions{width:100%}.detail-toolbar button{min-width:0;flex:1;padding:0 6px}.detail-list{padding-left:12px;padding-right:12px}.track-order button{width:25px}}
